import os,sys,json,pathlib,hashlib,runpy
from fireprot.adapters.atlasfold import runtime
chunk=int(os.environ.get('FIREPROT_ATLAS_CHUNK_TRIAL','128'))
assert chunk in (128,256)
original=runtime.triangle_attention
counts={'attention_calls':0}
def attention(*args,**kwargs):
    counts['attention_calls']+=1
    kwargs['chunk_size']=chunk
    return original(*args,**kwargs)
runtime.triangle_attention=attention
try:
    runpy.run_module('benchmarks.atlasfold.profile_inference',run_name='__main__')
finally:
    p=pathlib.Path(sys.argv[sys.argv.index('--out')+1])/'manifest.json'
    if p.exists():
        r=json.loads(p.read_text())
        r['experimental_candidate']={'name':'outer-attention-chunk-size','chunk_size':chunk,'counts':counts,'script_sha256':hashlib.sha256(pathlib.Path(__file__).read_bytes()).hexdigest()}
        if r.get('fireprot'):r['fireprot']['chunk_size']=chunk
        p.write_text(json.dumps(r,indent=2)+'\n')

